package com.example.starter.compliance.domain;

/**
 * 配方生命周期状态：SUBMITTED 已提交 → REVIEWED 已合规审查 → APPROVED 已批准（版本冻结）。
 */
public enum FormulaState {
    SUBMITTED,
    REVIEWED,
    APPROVED
}

package com.example.starter.compliance.domain;

/**
 * 量产备案状态：
 * ACTIVE 有效；REVIEW_WATCH 复审观察（标准更新后 90 个 UTC 自然日内）；
 * SUSPENDED 暂停（逾期未复审／复审不通过／被新版本取代）；CANCELLED 注销终态。
 */
public enum FilingStatus {
    ACTIVE,
    REVIEW_WATCH,
    SUSPENDED,
    CANCELLED
}

package com.example.starter.compliance.domain;

import java.math.BigDecimal;

/**
 * 配方中直接添加的添加剂。
 *
 * @param additiveCode 添加剂目录编码
 * @param amount       添加量，单位 g/kg（每千克终产品中克数）
 */
public record DirectAdditive(String additiveCode, BigDecimal amount) {
}

package com.example.starter.compliance.domain;

import java.math.BigDecimal;

/**
 * 配方使用的复合配料。
 *
 * @param ingredientCode 复合配料目录编码
 * @param ratio          配料占终产品质量比（0~1，无量纲）
 */
public record IngredientUse(String ingredientCode, BigDecimal ratio) {
}

package com.example.starter.compliance.domain;

import java.util.List;

/**
 * 配方完整业务内容（提交入参与存储模型共用）。
 *
 * @param productCode 产品编码
 * @param productName 产品名称
 * @param categoryCode 食品分类编码
 * @param version    配方版本号（同一产品内唯一）
 * @param additives  直接添加的添加剂列表
 * @param ingredients 复合配料使用列表
 */
public record FormulaContent(
        String productCode,
        String productName,
        String categoryCode,
        Integer version,
        List<DirectAdditive> additives,
        List<IngredientUse> ingredients) {
}

