package com.example.starter.compliance;

import org.springframework.http.HttpStatus;

/**
 * 业务异常，携带 HTTP 状态码与稳定错误码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }
}

package com.example.starter.compliance.time;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import org.springframework.stereotype.Component;

/**
 * 可控时钟：默认使用系统 UTC 时间；测试可设置固定时刻以验证 UTC 日界与复审期限。
 */
@Component
public class ComplianceClock {

    private volatile Instant fixed;

    public void setFixed(Instant instant) {
        this.fixed = instant;
    }

    public void reset() {
        this.fixed = null;
    }

    public Instant now() {
        Instant value = fixed;
        return value != null ? value : Instant.now();
    }

    public long nowMillis() {
        return now().toEpochMilli();
    }

    /** 当前 UTC 自然日序号（epochDay），复审 90 日期限按此日界计算。 */
    public long todayEpochDay() {
        return LocalDate.ofInstant(now(), ZoneOffset.UTC).toEpochDay();
    }
}

package com.example.starter.compliance.web;

import java.math.BigDecimal;
import java.util.List;

/**
 * 接口请求 DTO 集合；amount 单位 g/kg，ratio 为质量比（0~1）。
 */
public final class Requests {

    private Requests() {
    }

    public record DirectAdditiveDto(String additiveCode, BigDecimal amount) {
    }

    public record IngredientDto(String ingredientCode, BigDecimal ratio) {
    }

    public record SubmitFormulaRequest(
            String requestId,
            String productCode,
            String productName,
            String categoryCode,
            Integer version,
            List<DirectAdditiveDto> additives,
            List<IngredientDto> ingredients) {
    }

    public record FormulaRefRequest(String requestId, Long formulaId) {
    }

    public record FilingRefRequest(String requestId, Long filingId) {
    }

    public record FileFilingRequest(String requestId, Long formulaId) {
    }

    public record StandardUpdateRequest(
            String requestId,
            String additiveCode,
            String categoryCode,
            BigDecimal maxAmount) {
    }

    public record ProductionReportRequest(
            String requestId,
            Long filingId,
            String batchNo,
            BigDecimal quantityKg) {
    }
}

package com.example.starter.compliance.engine;

import java.math.BigDecimal;
import java.util.List;

/**
 * 合规审查纯计算模型（无数据库依赖，可独立复算）。
 */
public final class ReviewModels {

    private ReviewModels() {
    }

    /** 审查时对某一添加剂的逐项判定明细。 */
    public record ItemResult(
            String additiveCode,
            String functionCode,
            BigDecimal directAmount,
            BigDecimal carriedAmount,
            BigDecimal totalAmount,
            BigDecimal limitAmount,
            BigDecimal usageRatio,
            boolean passed,
            String reason) {
    }

    /** 同功能添加剂并用比例判定（各用量占限量比例之和，恰等 1 合法）。 */
    public record GroupResult(
            String functionCode,
            List<String> additiveCodes,
            BigDecimal combinedRatio,
            boolean passed) {
    }

    /** 一次完整合规审查报告。 */
    public record ReviewReport(
            boolean passed,
            String categoryCode,
            List<ItemResult> items,
            List<GroupResult> groups,
            long evaluatedAt) {
    }
}

