            normalize(root);
            return CANALYZER(root);
        } catch (JsonProcessingException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static String CANALYZER(JsonNode root) throws JsonProcessingException {
        return CANONICAL.writeValueAsString(root);
    }

    private static void normalize(JsonNode node) {
        if (node == null) {
            return;
        }
        if (node.isObject()) {
            ObjectNode object = (ObjectNode) node;
            Iterator<Map.Entry<String, JsonNode>> fields = object.fields();
            while (fields.hasNext()) {
                Map.Entry<String, JsonNode> field = fields.next();
                JsonNode child = field.getValue();
                if (child.getNodeType() == JsonNodeType.NUMBER && child instanceof DecimalNode decimal) {
                    BigDecimal normalized = decimal.decimalValue().stripTrailingZeros();
                    object.put(field.getKey(), normalized.toPlainString());
                } else {
