/**
 * requestId 幂等包装：指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果（含首次状态码），
 * 同键异参返回 409；并发同键插入由主键冲突收敛为重放或 409。
 */
private <T> ServiceResult<T> withIdempotency(String requestId, Object params, Class<T> type,
        Supplier<Outcome<T>> action) {
    if (requestId == null || requestId.isBlank()) {
        throw new ApiException(HttpStatus.BAD_REQUEST, "REQUEST_ID_REQUIRED",
                "变更接口必须提供 requestId");
    }
    String fingerprint = fingerprint(requestId, params);
    Optional<com.example.starter.compliance.repo.IdempotentRow> existing =
            repository.findIdempotent(requestId);
    if (existing.isPresent()) {
        com.example.starter.compliance.repo.IdempotentRow row = existing.get();
        if (!row.fingerprint().equals(fingerprint)) {
            throw new ApiException(HttpStatus.CONFLICT, "REQUEST_PARAM_CONFLICT",
                    "requestId 已用于不同业务参数");
        }
        return ServiceResult.replay(JsonSupport.read(row.responseJson(), type),
                row.statusCode());
    }

    Outcome<T> outcome = action.get();
    try {
        repository.insertIdempotent(requestId, fingerprint, outcome.status(),
                JsonSupport.write(outcome.body()), clock.nowMillis());
    } catch (DoubleKeyExceptionPlaceholder e) {
        throw new IllegalStateException(e);
    } catch (DuplicateKeyException e) {
        com.example.starter.compliance.repo.IdempotentRow raced =
                repository.findIdempotent(requestId)
                        .orElseThrow(() -> new ApiException(HttpStatus.CONFLICT,
                                "REQUEST_PARAM_CONFLICT", "requestId 并发冲突"));
        if (!raced.fingerprint().equals(fingerprint)) {
            throw new ApiException(HttpStatus.CONFLICT, "REQUEST_PARAM_CONFLICT",
                    "requestId 已用于不同业务参数");
        }
        return ServiceResult.replay(JsonSupport.read(raced.responseJson(), type),
                raced.statusCode());
    }
    return new ServiceResult<>(outcome.body(), false, outcome.status());
}

